#pragma once

#include <QDateTime>
#include <QJsonObject>
#include <QList>
#include <QMap>
#include <QSet>
#include <QString>
#include <QStringList>

#include <optional>

// Transcripts for PhraseFind AI and the Transcript Tool (Editing Guide ch.14, p.436-453; docs/spec/transcripts.md).
//
// "Transcripts are generated by analyzing and indexing all audible dialog for individual clips" (p.442): a transcript
// is a master clip's words, each with its time, in lines, each line with its Speaker ID. "Only master clips are
// transcribed" (p.448); subclips, groups and sequences reference their master clips' transcripts. Transcripts are
// kept in a store outside the project, one file per clip keyed by the clip's MobID, because "Transcripts for clips that
// have already been transcribed are available for use across multiple projects" (p.442).
//
// media::transcribeClip makes them through an ext::TranscriptionProvider; MainWindow runs that in the background for
// the bins included in transcription (TranscriptionBins).
namespace lumenis::model {

// One word, its times in seconds from the clip's first frame.
struct TranscriptWord {
    QString text;
    double start = 0.0;
    double end = 0.0;
    bool operator==(const TranscriptWord&) const = default;
};

// A line of words spoken by one speaker (the Transcript Tool's rows, p.443-444).
struct TranscriptLine {
    int speaker = 1; // Speaker ID: "Speaker 1", "Speaker 2" ... until named (Transcript::speakers)
    QList<TranscriptWord> words;
    bool operator==(const TranscriptLine&) const = default;

    // The words joined by spaces.
    QString text() const;
    double start() const { return words.isEmpty() ? 0.0 : words.first().start; }
    double end() const { return words.isEmpty() ? 0.0 : words.last().end; }
};

struct Transcript {
    QString mob;       // the master clip's MobID (MobId::toString), the store's key
    QString clipName;  // for messages and Manage Transcripts
    QString language;  // what the engine detected or was told (the Language Hint, p.448)
    QDateTime created;
    QList<TranscriptLine> lines;
    // "Media Composer preserves the original transcript generated when the clip was transcribed. Edited transcripts are
    // stored separately, allowing transcript changes to be reverted" (2026.8 guide p.447): the lines as transcribed,
    // kept once the transcript is first edited; empty until then.
    QList<TranscriptLine> original;
    // Speaker names by Speaker ID ("All instance of that speaker name in the transcript are immediately renamed",
    // p.445); an ID without a name shows as "Speaker n".
    QMap<int, QString> speakers;

    bool edited() const { return !original.isEmpty(); }
    // The name a Speaker ID shows.
    QString speakerName(int speaker) const;
    // Every line, "Speaker: words", one per line of text.
    QString plainText() const;

    QJsonObject toJson() const;
    static std::optional<Transcript> fromJson(const QJsonObject& o);
};

// A word as an engine gives it, and whether the speaker changes after it (whisper.cpp's tinydiarize speaker turns).
struct EngineWord {
    QString text;
    double start = 0.0;
    double end = 0.0;
    bool turnAfter = false;
};

// Words from an engine as transcript lines. A line ends at a speaker turn, at a pause of more than `pause` seconds and
// after a word ending a sentence when the line already lasts `longest` seconds (ours: the guide leaves line breaks to
// the engine). Speaker IDs alternate at turns between the speakers already heard, a new turn taking the next ID (ours:
// tinydiarize marks turns, not voices). Empty words are left out.
QList<TranscriptLine> transcriptLines(const QList<EngineWord>& words, double pause = 2.0, double longest = 30.0);

// Editing transcripts (Editing Guide p.445-446; 2026.8 guide p.446-447). Each function changes `t` and returns false (with
// `t` unchanged) when there is nothing to do. The first change keeps the lines as transcribed in Transcript::original.

// Replaces the words [from, to) of line `line` with the words of `text`, keeping word timing (p.446): "Single word edits:
// The original word's timing is preserved. Multiple words in one word's space: Timings split averaging across the new
// words. Multiple word edits: ... compares the original and edited text to align unchanged words, then adjusts timings
// for the words between them". Ours: unchanged words are found by the longest common sequence of words (ignoring case
// and punctuation); the words between two kept ones share their time evenly. "Only one sentence can be edited at a
// time": one line. An empty `text` removes the words (the line too when none are left).
bool editWords(Transcript& t, int line, int from, int to, const QString& text);
// Find and Replace (p.446): every place the words of `find` follow one another in a line, ignoring case and punctuation,
// becomes `replace`. Returns how many were replaced.
int replaceWords(Transcript& t, const QString& find, const QString& replace);

// Speaker IDs (p.444-445). renameSpeaker: "All instance of that speaker name in the transcript are immediately renamed";
// an empty name clears it ("Clear Name"). identifySpeaker: the line's speaker becomes the one named `name` (a new ID when
// no speaker has that name), "Identify Speaker". correctSpeaker: "Correct Speaker ID" for one line: the speaker `speaker`,
// or with 0 "Add New Speaker", a new ID "that can be identified in this one instance".
bool renameSpeaker(Transcript& t, int speaker, const QString& name);
bool identifySpeaker(Transcript& t, int line, const QString& name);
bool correctSpeaker(Transcript& t, int line, int speaker);
// The speaker IDs in use, ascending.
QList<int> speakerIds(const Transcript& t);

// Start New Line (2026.8 guide p.447): the line splits before word `word` (1 or more), both halves keeping the speaker.
bool startNewLine(Transcript& t, int line, int word);
// Revert (2026.8 guide p.447): the original lines in the time of line `line` take its place; Revert Transcript: every line
// as transcribed. "Reverting restores the original transcript content".
bool revertLine(Transcript& t, int line);
bool revertTranscript(Transcript& t);

// The store of transcripts: a folder of "<MobID>.json" files. Thread-safe as long as one clip is written by one thread.
class TranscriptStore {
public:
    explicit TranscriptStore(QString folder = defaultFolder());
    // LUMENIS_TRANSCRIPTS when set (tests), else "Transcripts" in the user's application data.
    static QString defaultFolder();
    QString folder() const { return folder_; }

    bool has(const QString& mob) const;
    std::optional<Transcript> load(const QString& mob) const;
    // Writes the transcript (creating the folder); false when it cannot be written.
    bool save(const Transcript& transcript) const;
    // Deletes a clip's transcript ("Delete Transcript", 2026.8 guide p.455); false when there was none.
    bool remove(const QString& mob) const;
    // Every transcribed clip's MobID.
    QStringList mobs() const;

private:
    QString path(const QString& mob) const;
    QString folder_;
};

// Which bins are transcribed (p.446-447): "right-click on a bin and choose Include Bin in Transcription or Exclude Bin
// from Transcription". Kept in the project folder, not the bins ("When copying or moving bins on the macOS Finder or
// Windows Explorer level, the status of transcription will not be moved with it"), by the bins' node ids. A bin not
// listed is included unless it was made while "Include all new bins in transcription" was off (setExcluded at its
// creation).
class TranscriptionBins {
public:
    TranscriptionBins() = default;
    // Reads "<project folder>/Transcription.json"; nothing there leaves every bin included.
    explicit TranscriptionBins(QString projectFolder);
    bool isIncluded(const QString& binId) const { return !excluded_.contains(binId); }
    // Changes and writes the file; false when it cannot be written.
    bool setIncluded(const QString& binId, bool included);
    QSet<QString> excluded() const { return excluded_; }

private:
    QString file_;
    QSet<QString> excluded_;
};

} // namespace lumenis::model
